	internal class _Anon_AbstractGColumnRenderer_1 : AbstractGColumnRenderer<>
	{

			/* @Override */
			public Component getTableCellRendererComponent(GTableCellRenderingData data) {

				object value = data.getValue();
				bool isSelected = data.isSelected();

				string addressSource = (value != null) ? (string) value : NO_SOURCE_TEXT;
				string sourceString = getText(value);

				GTableCellRenderingData renderData = data.copyWithNewValue(sourceString);

				JLabel renderer = (JLabel) base.getTableCellRendererComponent(renderData);

				if (NO_SOURCE_TEXT.equals(addressSource)) {
					setForeground(FG_ERROR);
				}
				else if (VTMarkupItem.USER_DEFINED_ADDRESS_SOURCE.equals(addressSource)) {
					setForeground(isSelected ? FG_USER_DEFINED : FG_USER_DEFINED_SELECTED);
				}

				renderer.setOpaque(true);

				return renderer;
			}

			private string getText(string value) {
				string addressSource = (value != null) ? (string) value : NO_SOURCE_TEXT;
				string sourceString = "(" + addressSource + ")";
				return sourceString;
			}

			/* @Override */
			public string getFilterString(string t, Settings settings) {
				return getText(t);
			}
		
	}


